contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        require(_feeRate > 5000);

        bool reverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && !c.initialized() && c.feeRate() == 0 && c.baseToken() == address(0));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        require(_feeRate <= 5000);

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        bool secondReverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(
            c.initialized() &&
            c.baseToken() == _baseToken &&
            c.nft() == _nft &&
            c.virtualBaseTokenReserves() == _virtualBaseTokenReserves &&
            c.virtualNftReserves() == _virtualNftReserves &&
            c.changeFee() == _changeFee &&
            c.feeRate() == _feeRate &&
            c.merkleRoot() == _merkleRoot &&
            c.useStolenNftOracle() == _useStolenNftOracle &&
            c.payRoyalties() == _payRoyalties &&
            secondReverted
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 tokenId, uint256 weight, uint256 wrongWeight) public {
        require(weight != wrongWeight);

        bytes32 leaf = keccak256(bytes.concat(keccak256(abi.encode(tokenId, weight))));

        c.initialize(
            address(0),
            address(0),
            1e18,
            1e18,
            0,
            0,
            leaf,
            false,
            false
        );

        uint256[] memory ids = new uint256[](1);
        ids[0] = tokenId;
        uint256[] memory ws = new uint256[](1);
        ws[0] = weight;
        bool[] memory noFlags = new bool[](0);
        bytes32[] memory noProof = new bytes32[](0);
        C.MerkleMultiProof memory proof = C.MerkleMultiProof(noProof, noFlags);

        uint256 sum = c.sumWeightsAndValidateProof(ids, ws, proof);

        uint256[] memory wsWrong = new uint256[](1);
        wsWrong[0] = wrongWeight;
        bool reverted;
        try c.sumWeightsAndValidateProof(ids, wsWrong, proof) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(sum == weight && reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint128 vbr, uint128 vnr, uint256 outputAmount, uint16 feeRate) public {
        require(vbr > 0 && vnr > 1);
        require(outputAmount > 0 && outputAmount < vnr);
        require(feeRate <= 5000);
        require(uint256(outputAmount) * vbr < type(uint256).max - uint256(vnr));

        c.initialize(
            address(0),
            address(0),
            vbr,
            vnr,
            0,
            feeRate,
            bytes32(0),
            false,
            false
        );

        uint256 d = uint256(vnr) - outputAmount;
        uint256 expectedInput = (uint256(outputAmount) * vbr + d - 1) / d;

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount);

        assert(
            netInputAmount == expectedInput + feeAmount + protocolFeeAmount &&
            feeAmount == (expectedInput * uint256(feeRate)) / 10000
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint128 vbr, uint128 vnr, uint256 inputAmount, uint16 feeRate) public {
        require(vbr > 0 && vnr > 0);
        require(inputAmount > 0 && uint256(vnr) + inputAmount > uint256(vnr));
        require(feeRate <= 5000);
        require(uint256(inputAmount) * vbr < type(uint256).max / 2);

        c.initialize(address(0), address(0), vbr, vnr, 0, feeRate, bytes32(0), false, false);

        uint256 out = (uint256(inputAmount) * vbr) / (uint256(vnr) + inputAmount);
        uint256 expectedFee = (out * uint256(feeRate)) / 10000;

        (uint256 netOutputAmount, uint256 feeAmount, ) = c.sellQuote(inputAmount);

        assert(netOutputAmount == out - expectedFee && feeAmount == expectedFee);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 vbr,
        uint128 vnr,
        uint56 changeFee,
        uint16 feeRate,
        uint256 w
    ) public payable {
        require(vnr > 0);
        require(w < vnr);
        require(vbr <= 1e30);
        require(feeRate <= 5_000);

        c.initialize(
            address(0),
            address(0xdead),
            vbr,
            vnr,
            changeFee,
            feeRate,
            bytes32(0),
            false,
            false
        );

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(w);

        uint256 expectedInput = FixedPointMathLib.mulDivUp(w, vbr, uint256(vnr) - w);

        assert(
            netInputAmount == expectedInput + feeAmount + protocolFeeAmount &&
            feeAmount == expectedInput * uint256(feeRate) / 10_000 &&
            feeAmount <= netInputAmount &&
            protocolFeeAmount <= netInputAmount
        );
    }

    receive() external payable {}
}

